use verus::prelude::*; // or `use vstd::prelude::*;` depending on your setup

/// Takes two equal‐length byte‐vectors `a` and `b` and returns a new
/// vector whose i’th element is `a[i] ^ b[i]`.
#[requires(a.len() == b.len())]
#[ensures(result.len() == a.len())]
#[ensures( forall(|i: usize| i < a.len() ==> result[i] == a[i] ^ b[i]) )]
fn bitwise_xor(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // We keep the runtime assertion for extra safety,
    // even though the spec already requires them to be equal.
    assert_eq!(
        a.len(),
        b.len(),
        "Input vectors must have the same length"
    );

    // Consume both vectors, zip their elements, xor them, and collect into a new Vec<u8>
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x ^ y)
     .collect()
}

